interface Shape { double area(); }

class Circle implements Shape {
    private double r;

    Circle(double r) {
        this.r = r;
    }

    public double area() {
        return Math.PI * r * r;
    }
}

class Rect implements Shape {
    private double w;
    private double h;

    Rect(double w, double h) {
        this.w = w;
        this.h = h;
    }

    public double area() {
        return w * h;
    }
}

public class Main {
    static double totalArea(Shape[] shapes) {
        double total = 0;
        for (Shape s : shapes) {
            total += s.area();
        }
        return total;
    }

    public static void main(String[] args) {
        Shape[] shapes = {new Rect(2, 3), new Rect(4, 5)};
        System.out.println(totalArea(shapes));
    }
}

