class Book {
    private String title;
    private boolean available = true;

    Book(String title) {
        this.title = title;
    }

    String getTitle() {
        return title;
    }

    boolean isAvailable() {
        return available;
    }

    boolean borrow() {
        if (!available) {
            return false;
        }
        available = false;
        return true;
    }
}

class Library {
    private Book[] books = new Book[10];
    private int count = 0;

    void add(Book b) {
        books[count++] = b;
    }

    boolean borrow(String title) {
        for (int i = 0; i < count; i++) {
            if (books[i].getTitle().equals(title)) {
                return books[i].borrow();
            }
        }
        return false;
    }

    int availableCount() {
        int n = 0;
        for (int i = 0; i < count; i++) {
            if (books[i].isAvailable()) {
                n++;
            }
        }
        return n;
    }
}

public class Main {
    public static void main(String[] args) {
        Library lib = new Library();
        lib.add(new Book("Godan"));
        lib.add(new Book("Gitanjali"));
        System.out.println(lib.borrow("Godan") + " " + lib.borrow("Godan"));
        System.out.println("Available: " + lib.availableCount());
    }
}
